def backup_existing_tree() -> Path | None:
    """Back up the existing RC5 Coding tree when it exists."""

    if not APP.exists():
        return None

    timestamp = datetime.now(UTC).strftime("%Y%m%d_%H%M%S")
    backup = BACKUP_ROOT / timestamp
    backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(APP, backup)
    return backup


def recreate_tree() -> None:
    """Remove the old Coding tree and recreate it."""

    if APP.exists():
        shutil.rmtree(APP)
    APP.mkdir(parents=True, exist_ok=True)


def repair_model_registration() -> None:
    """Harden Coding into the parent Revenue Cycle namespace."""

    model_paths = (
        ROOT / "apps" / "revenue_cycle" / "coding" / "models" / "coding_record.py",
        ROOT / "apps" / "revenue_cycle" / "coding" / "models" / "code_assignment.py",
    )

    for path in model_paths:
        source = path.read_text(encoding="utf-8")
        source = source.replace(
            'app_label = "revenue_cycle_coding"',
            'app_label = "revenue_cycle"',
        )
        source = source.replace(
            'app_label = "coding"',
            'app_label = "revenue_cycle"',
        )
        source = source.replace(
            '"revenue_cycle_coding.CodingRecord"',
            '"revenue_cycle.CodingRecord"',
        )
        if 'app_label = "revenue_cycle"' not in source:
            source = source.replace(
                "    class Meta:\n",
                '    class Meta:\n        app_label = "revenue_cycle"\n',
                1,
            )
        path.write_text(source, encoding="utf-8", newline="\n")


def repair_legacy_namespace_references() -> None:
    """Normalize legacy Coding namespace references across the rebuilt source."""

    for path in APP.rglob("*.py"):
        source = path.read_text(encoding="utf-8")
        repaired = source.replace("revenue_cycle_coding", "revenue_cycle")
        if repaired != source:
            path.write_text(repaired, encoding="utf-8", newline="\n")


def write_files() -> None:
    """Write every source file in the rebuilt package."""

    for relative_path, content in FILES.items():
        target = APP / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")


def validate_no_collisions() -> None:
    """Reject module/package collisions."""

    names = (
        "events",
        "permissions",
        "policies",
        "selectors",
        "services",
        "workflows",
    )

    for name in names:
        module = APP / f"{name}.py"
        package = APP / name
        if module.exists() and package.exists():
            raise RuntimeError(f"Package collision detected: {module} and {package}")

    for module_name, package_name in (
        ("views.py", "views"),
        ("serializers.py", "serializers"),
    ):
        module = APP / "api" / module_name
        package = APP / "api" / package_name
        if module.exists() and package.exists():
            raise RuntimeError(
                f"API package collision detected: {module} and {package}"
            )


def validate_python() -> None:
    """Parse every Python file in the rebuilt package."""

    for source in APP.rglob("*.py"):
        ast.parse(
            source.read_text(encoding="utf-8"),
            filename=str(source),
        )


def validate_canonical_patient() -> None:
    """Ensure CodingRecord uses the canonical Patient model."""

    source = (APP / "models" / "coding_record.py").read_text(encoding="utf-8")

    expected = "from apps.patient_management.patients.models import Patient"

    if expected not in source:
        raise RuntimeError("Canonical Patient import is missing from CodingRecord.")

    if "apps.clinical.patients" in source:
        raise RuntimeError("Legacy clinical Patient import detected.")


def validate_required_api() -> None:
    """Ensure all required API views are exported."""

    source = (APP / "api" / "views" / "__init__.py").read_text(encoding="utf-8")

    required = (
        "CodeAssignmentAPIView",
        "CodingDetailAPIView",
        "CodingListCreateAPIView",
        "CodingRestoreAPIView",
        "CodingTransitionAPIView",
    )

    for symbol in required:
        if symbol not in source:
            raise RuntimeError(f"Required API export missing: {symbol}")


def validate_canonical_rbac() -> None:
    """Ensure Coding uses the canonical RBAC resolver."""

    source = (APP / "rbac.py").read_text(encoding="utf-8")
    if "from apps.platform.rbac.resolvers import resolve_permissions" not in source:
        raise RuntimeError(
            "Canonical RBAC resolver import is missing from Coding RBAC adapter."
        )
    if "user_has_permission" in source:
        raise RuntimeError("Legacy user_has_permission RBAC engine reference detected.")


def validate_model_namespace() -> None:
    """Ensure Coding models and relations use the parent Revenue Cycle namespace."""

    for name in ("coding_record.py", "code_assignment.py"):
        source = (APP / "models" / name).read_text(encoding="utf-8")
        if 'app_label = "revenue_cycle"' not in source:
            raise RuntimeError(f"{name} is not registered under revenue_cycle.")
        if "revenue_cycle_coding" in source:
            raise RuntimeError(
                f"Legacy revenue_cycle_coding namespace detected in {name}."
            )

    for path in APP.rglob("*.py"):
        source = path.read_text(encoding="utf-8")
        if "revenue_cycle_coding" in source:
            raise RuntimeError(
                f"Legacy revenue_cycle_coding namespace detected in {path.name}."
            )


def validate_api_package() -> None:
    """Ensure the complete Coding API package was installed."""

    required = (
        APP / "api" / "__init__.py",
        APP / "api" / "urls.py",
        APP / "api" / "serializers" / "__init__.py",
        APP / "api" / "serializers" / "coding.py",
        APP / "api" / "views" / "__init__.py",
        APP / "api" / "views" / "coding.py",
    )
    missing = [str(path) for path in required if not path.exists()]
    if missing:
        raise RuntimeError("Incomplete Coding API source:\n" + "\n".join(missing))


def validate_migration_policy() -> None:
    """Ensure the rebuild did not create migration files."""

    migration_files = tuple(APP.glob("migrations/[0-9]*.py"))

    if migration_files:
        raise RuntimeError(
            "Migration generation policy violated: "
            + ", ".join(str(path) for path in migration_files)
        )


def write_manifest() -> None:
    """Write the RC5 installer manifest."""

    manifest = {
        "module": "revenue_cycle.coding",
        "version": VERSION,
        "canonical_patient": ("apps.patient_management.patients.models.Patient"),
        "organization": ("apps.platform.organizations.models.Organization"),
        "migration_policy": "no_migrations_generated",
        "database_policy": "no_database_modification",
        "collision_policy": "remove_module_package_collisions",
    }

    (APP / ".installer_manifest.json").write_text(
        json.dumps(manifest, indent=2) + "\n",
        encoding="utf-8",
    )


def validate_installer_symbols() -> None:
    """Validate installer path symbols before touching the project tree."""

    if "BASE" in globals():
        raise RuntimeError("Obsolete BASE installer symbol is present.")

    if "ROOT" not in globals():
        raise RuntimeError("ROOT installer symbol is missing.")


def main() -> int:
    """Install the production RC5 Coding rebuild safely."""

    validate_installer_symbols()

    # Patient Management and Family Members are canonical/frozen domains.
    # The retired legacy apps.clinical.patients package is intentionally absent
    # and MUST NOT be required for a successful Coding installation.
    protected_required = (
        ROOT / "apps" / "patient_management",
        ROOT / "apps" / "patient_management" / "family_members",
        ROOT / "apps" / "revenue_cycle" / "claim_scrubbing",
    )
    missing_protected = [str(path) for path in protected_required if not path.exists()]
    if missing_protected:
        raise RuntimeError(
            "Required protected domain missing: " + ", ".join(missing_protected)
        )

    legacy_patient = ROOT / "apps" / "clinical" / "patients"
    if legacy_patient.exists():
        print("LEGACY CLINICAL PATIENT DOMAIN: PRESENT (UNTOUCHED)")
    else:
        print("LEGACY CLINICAL PATIENT DOMAIN: ABSENT (EXPECTED)")

    print("=" * 78)
    print("DatavionAI Revenue Cycle RC5 Coding Complete Rebuild Installer v5.2.0")
    print("=" * 78)

    backup = backup_existing_tree()

    if backup is not None:
        print(f"BACKUP CREATED: {backup}")
    else:
        print("BACKUP: Existing RC5 Coding tree not found.")

    recreate_tree()
    write_files()
    repair_model_registration()
    repair_legacy_namespace_references()
    write_manifest()

    validate_no_collisions()
    print("PACKAGE COLLISIONS: NONE")

    validate_python()
    print("AST VALIDATION: PASS")

    validate_canonical_patient()
    print("CANONICAL PATIENT: PASS")

    validate_canonical_rbac()
    print("CANONICAL RBAC: PASS")

    validate_model_namespace()
    print("MODEL NAMESPACE: revenue_cycle")

    validate_api_package()
    print("COMPLETE API PACKAGE: PASS")

    validate_required_api()
    print("API EXPORTS: PASS")

    validate_migration_policy()
